using System.Text.Json.Nodes;
using System.IO.Compression;
using System.Xml;
using System.Xml.Linq;
namespace MyProjectManagement;
public static class ChangeRequests {
 public static readonly string[] Flags=["createChangeRequests","reviewChangeRequestsPM","reviewChangeRequestsCTO","viewAllChangeRequests"];
 public static bool Default(string role,string scope,string flag)=>flag switch{"createChangeRequests"=>role!="CTO"&&new[]{"Project manager","Project lead","ERP consultant"}.Contains(scope),"reviewChangeRequestsPM"=>role!="CTO"&&scope=="Project manager","reviewChangeRequestsCTO"=>role=="CTO",_=>false};
 public static void Seed(JsonObject settings){var roles=MasterData.Roles(settings);foreach(var pair in new[]{("CTO","CTO","Project manager"),("Team lead","TL","Project lead")})if(!roles.OfType<JsonObject>().Any(r=>J.S(r,"name")==pair.Item1)){var code=roles.OfType<JsonObject>().Any(r=>J.S(r,"code")==pair.Item2)?"CR_"+Guid.NewGuid().ToString("N")[..8]:pair.Item2;var label=roles.OfType<JsonObject>().Any(r=>J.S(r,"label")==pair.Item1)?pair.Item1+" "+Guid.NewGuid().ToString("N")[..4]:pair.Item1;roles.Add(new JsonObject{["name"]=pair.Item1,["label"]=label,["code"]=code,["baseRole"]=pair.Item3,["active"]=true,["description"]="Change request workflow role"});}settings["roleMaster"]=roles;settings["rolePermissions"]??=new JsonObject();foreach(var r in roles.OfType<JsonObject>()){string role=J.S(r,"name");settings["rolePermissions"]![role]??=new JsonObject();foreach(var flag in Flags)if(settings["rolePermissions"]![role]![flag] is null)settings["rolePermissions"]![role]![flag]=Default(role,J.S(r,"baseRole"),flag);}}
 public static JsonObject Latest(JsonObject row)=>row["revisions"]!.AsArray().Last()!.AsObject();
 public static bool MemberFlag(Snapshot s,string id,string flag){if(!s.Members.TryGetValue(id,out var m)||!J.B(m,"active",true)||!MasterData.RoleActive(s.Settings,J.S(m,"role")))return false;var role=J.S(m,"role");return s.Settings["rolePermissions"]?[role]?[flag] is JsonValue v&&v.TryGetValue<bool>(out var enabled)?enabled:Default(role,MasterData.BaseRole(s.Settings,role),flag);}
 public static bool Read(Policy p,JsonObject row)=>p.Active&&(p.Owner||J.S(row,"initiatorId")==p.Actor||J.A(row,"revisions").Any(r=>J.S(r,"pmId")==p.Actor||J.S(r,"ctoId")==p.Actor)||p.Flag("viewAllChangeRequests")&&p.ProjectScope(J.S(row,"projectId")));
 static string Text(JsonObject body,string name,int max,bool required=false){var text=J.S(body,name).Trim();J.Require(text.Length<=max&&(!required||text!=""),"Enter "+name+" (maximum "+max+" characters)",400);return text;}
 static void DraftFields(Snapshot s,JsonObject row,JsonObject revision,JsonObject body){var project=s.Records.GetValueOrDefault("project:"+J.S(row,"projectId"));J.Require(project is not null,"Project no longer exists",400);string pm=J.S(project,"projectManager"),cto=Text(body,"ctoId",100,true),initiator=J.S(row,"initiatorId");J.Require(pm!=""&&MemberFlag(s,pm,"reviewChangeRequestsPM"),"Assign an active Project Manager with CR feasibility permission in Project Master",400);J.Require(MemberFlag(s,cto,"reviewChangeRequestsCTO"),"Select an active CTO approver with CR CTO permission",400);J.Require(pm!=cto&&pm!=initiator&&cto!=initiator,"Initiator, Project Manager and CTO must be different people",400);
 revision["title"]=Text(body,"title",150,true);revision["description"]=Text(body,"description",6000,true);revision["reason"]=Text(body,"reason",4000,true);revision["pmId"]=pm;revision["ctoId"]=cto;
 if(body["header"] is JsonObject){StructuredChangeRequest.Fields(row,revision,body);return;}
 var points=J.A(body,"points").ToList();J.Require(points.Count is >0 and <=50,"Enter 1–50 numbered change points",400);revision["points"]=new JsonArray(points.Select((point,i)=>(JsonNode)new JsonObject{["id"]="P"+(i+1),["text"]=Text(point,"text",2000,true)}).ToArray());
 }
 static void Event(JsonObject row,Policy p,string action,string note=""){var r=Latest(row);J.A(row,"audit").Count();(row["audit"]??=new JsonArray()).AsArray().Add(new JsonObject{["revision"]=(int)J.N(r,"number"),["action"]=action,["by"]=p.Actor,["at"]=DateTimeOffset.UtcNow.ToString("O"),["note"]=note});row["updatedAt"]=DateTimeOffset.UtcNow.ToString("O");}
 public static JsonObject Create(Snapshot s,Policy p,JsonObject body){J.Require(p.Active&&p.Flag("createChangeRequests")&&p.ProjectScope(J.S(body,"projectId")),"Change request creation requires project access and permission");var id=Guid.NewGuid().ToString();var row=new JsonObject{["id"]=id,["number"]="CR-"+Guid.NewGuid().ToString("N")[..12].ToUpperInvariant(),["projectId"]=J.S(body,"projectId"),["projectName"]=J.S(p.Project(J.S(body,"projectId")),"name"),["projectCode"]=J.S(p.Project(J.S(body,"projectId")),"code"),["customerId"]=J.S(p.Project(J.S(body,"projectId")),"customerId"),["initiatorId"]=p.Actor,["createdAt"]=DateTimeOffset.UtcNow.ToString("O"),["audit"]=new JsonArray(),["revisions"]=new JsonArray()};var revision=new JsonObject{["number"]=1,["state"]="Draft",["documents"]=new JsonArray(),["reviews"]=new JsonArray(),["createdAt"]=DateTimeOffset.UtcNow.ToString("O")};row["revisions"]!.AsArray().Add(revision);DraftFields(s,row,revision,body);Event(row,p,"Created draft");return row;}
 public static void Act(Snapshot s,Policy p,JsonObject row,string action,JsonObject body){J.Require(Read(p,row),"Change request access denied");var revision=Latest(row);var state=J.S(revision,"state");bool initiator=p.Actor==J.S(row,"initiatorId")&&p.Flag("createChangeRequests");
 if(action=="save"){J.Require(initiator&&state=="Draft","Only the initiator may edit the current draft");DraftFields(s,row,revision,body);Event(row,p,"Draft updated");}
 else if(action=="submit"){J.Require(initiator&&state=="Draft","Only the initiator may submit a draft");J.Require(J.S(revision,"documentId")!="","Upload a Word document for this revision before submitting",400);DraftFields(s,row,revision,revision);StructuredChangeRequest.Submit(row);revision["state"]="Pending PM";revision["submittedAt"]=DateTimeOffset.UtcNow.ToString("O");Event(row,p,"Submitted to Project Manager");}
 else if(action=="revise"){J.Require(initiator&&new[]{"Returned by PM","Meeting requested by PM","Returned by CTO","Meeting requested by CTO","Technically feasible"}.Contains(state),"A new revision can be started after a return, meeting request or technical approval");J.Require(row["revisions"]!.AsArray().Count<100,"Maximum 100 revisions reached",400);var reason=Text(body,"reason",4000,true);var next=new JsonObject{["number"]=(int)J.N(revision,"number")+1,["state"]="Draft",["title"]=J.S(revision,"title"),["description"]=J.S(revision,"description"),["reason"]=reason,["points"]=revision["points"]!.DeepClone(),["pmId"]=J.S(revision,"pmId"),["ctoId"]=J.S(revision,"ctoId"),["documents"]=new JsonArray(),["reviews"]=new JsonArray(),["createdAt"]=DateTimeOffset.UtcNow.ToString("O")};if(revision["header"] is JsonObject){next["header"]=revision["header"]!.DeepClone();next["sourceDocumentId"]=J.S(revision,"documentId");next["amendmentResponses"]=new JsonArray();}row["revisions"]!.AsArray().Add(next);Event(row,p,"New revision started",reason);}
 else if(action=="review"){StructuredChangeRequest.Review(row,p.Actor,body);string stage=state=="Pending PM"?"PM":state=="Pending CTO"?"CTO":"";J.Require(stage!=""&&p.Actor==J.S(revision,stage=="PM"?"pmId":"ctoId")&&p.Flag(stage=="PM"?"reviewChangeRequestsPM":"reviewChangeRequestsCTO"),"Only the assigned active-stage approver can decide this revision");var decision=Text(body,"decision",30,true);J.Require(new[]{"Approve","Amendment","Clarification","Meeting"}.Contains(decision),"Choose a valid decision",400);var general=Text(body,"comment",4000);var comments=J.A(body,"comments").ToList();J.Require(comments.Count<=100,"Maximum 100 point/paragraph comments",400);var validPoints=J.A(revision,"points").Select(x=>J.S(x,"id")).ToHashSet();var currentDocument=J.A(revision,"documents").FirstOrDefault(d=>J.S(d,"id")==J.S(revision,"documentId"));var paragraphs=(int)J.N(currentDocument,"paragraphCount");var notes=new JsonArray();foreach(var item in comments){var point=Text(item,"point",30,true);J.Require(validPoints.Contains(point)||(System.Text.RegularExpressions.Regex.IsMatch(point,"^D[1-9][0-9]{0,3}$")&&int.Parse(point[1..])<=paragraphs),"Use a change-point ID or document paragraph D1–D9999",400);notes.Add(new JsonObject{["point"]=point,["text"]=Text(item,"text",2000,true)});}J.Require(decision=="Approve"||general!=""||notes.Count>0,"Add clarification, amendment or meeting comments",400);var review=new JsonObject{["stage"]=stage,["decision"]=decision,["comment"]=general,["comments"]=notes,["by"]=p.Actor,["at"]=DateTimeOffset.UtcNow.ToString("O"),["documentId"]=J.S(revision,"documentId")};if(decision=="Meeting"){var date=Text(body,"meetingDate",10,true);J.Require(J.Day(date)>=J.Today,"Proposed meeting date cannot be in the past",400);review["meetingDate"]=date;review["meetingNote"]="Meeting requested; confirm and schedule through Meetings.";}
 revision["reviews"]!.AsArray().Add(review);revision["state"]=decision=="Approve"?(stage=="PM"?"Pending CTO":"Technically feasible"):decision=="Meeting"?"Meeting requested by "+stage:"Returned by "+stage;Event(row,p,stage+" - "+decision,general);}
 else throw new ApiError(400,"Unknown change-request action");
 }
 public static void Upload(Snapshot s,Policy p,JsonObject row,JsonObject metadata){J.Require(Read(p,row)&&p.Actor==J.S(row,"initiatorId")&&p.Flag("createChangeRequests")&&J.S(Latest(row),"state")=="Draft","Only the initiator may attach documents to the current draft");var r=Latest(row);r["documents"]!.AsArray().Add(metadata.DeepClone());r["documentId"]=J.S(metadata,"id");Event(row,p,"Word document uploaded",J.S(metadata,"name"));}
 public static JsonArray Preview(byte[] bytes,string name){var paragraphs=new JsonArray();if(!name.EndsWith(".docx",StringComparison.OrdinalIgnoreCase))return paragraphs;try{using var memory=new MemoryStream(bytes);using var zip=new ZipArchive(memory,ZipArchiveMode.Read);J.Require(!zip.Entries.Any(e=>e.FullName.EndsWith("vbaProject.bin",StringComparison.OrdinalIgnoreCase)),"Macro-enabled Word files are not supported",400);var entry=zip.GetEntry("word/document.xml");J.Require(entry is not null&&entry.Length<=4*1024*1024,"Invalid or oversized Word document contents",400);using var stream=entry!.Open();using var xml=XmlReader.Create(stream,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=4*1024*1024});var doc=XDocument.Load(xml);XNamespace ns="http://schemas.openxmlformats.org/wordprocessingml/2006/main";foreach(var para in doc.Descendants(ns+"p")){var text=string.Concat(para.Descendants(ns+"t").Select(x=>x.Value));if(text.Trim()=="")continue;paragraphs.Add(new JsonObject{["id"]="D"+(paragraphs.Count+1),["text"]=text.Length>5000?text[..5000]:text});if(paragraphs.Count>=2000)break;}return paragraphs;}catch(InvalidDataException){throw new ApiError(400,"Upload a valid Word .docx document");}catch(XmlException){throw new ApiError(400,"Word text could not be read; upload a valid .docx");}}
}
